steps.run:
$props = '.mvn/wrapper/maven-wrapper.properties'
# as on Linux: the wrapper keeps the last value of each key, a pattern check any line
foreach ($key in 'distributionUrl', 'distributionSha256Sum') {
  if ((Select-String -Path $props -Pattern "^$key=").Count -ne 1) {
    Write-Host "$props must set $key exactly once"
    exit 1
  }
}
if (-not (Select-String -Path $props -Pattern '^distributionSha256Sum=[0-9a-f]{64}$' -Quiet)) {
  Write-Host "the distribution checksum is not pinned"
  exit 1
}
# as on Linux: pin the source of the distribution, not only its digest
if (-not (Select-String -Path $props -Pattern '^distributionUrl=https://repo\.maven\.apache\.org/maven2/org/apache/maven/apache-maven/[0-9.]+/apache-maven-[0-9.]+-bin\.zip$' -Quiet)) {
  Write-Host "the distribution does not come from repo.maven.apache.org"
  exit 1
}
(Get-Content $props) -replace '^distributionSha256Sum=.*', ('distributionSha256Sum=' + ('0' * 64)) |
  Set-Content $props
$env:MAVEN_USER_HOME = (New-Item -ItemType Directory -Path (Join-Path $env:RUNNER_TEMP ([guid]::NewGuid()))).FullName
$output = & cmd /c "mvnw.cmd -v 2>&1"
$status = $LASTEXITCODE
$output | Write-Host
git checkout -- $props
# One string, single-spaced: PowerShell hands back an array of lines and wraps the
# error text across them, and -notmatch on an array filters instead of testing.
$joined = ($output | Out-String) -replace '\s+', ' '
if ($status -eq 0) {
  Write-Host "the wrapper ran Maven from a distribution that failed its checksum"
  exit 1
}
if (-not $joined.Contains('Failed to validate Maven distribution SHA-256')) {
  Write-Host "the wrapper failed, but not on the checksum - this check proved nothing"
  exit 1
}
Write-Host "the wrapper refused the tampered distribution on its checksum"
